diff --git a/src/main/java/org/jsoup/Jsoup.java b/src/main/java/org/jsoup/Jsoup.java
index d25c1869..29c7cb3d 100644
--- a/src/main/java/org/jsoup/Jsoup.java
+++ b/src/main/java/org/jsoup/Jsoup.java
@@ -244,10 +244,26 @@ public class Jsoup {
      @param bodyHtml HTML to test
      @param whitelist whitelist to test against
      @return true if no tags or attributes were removed; false otherwise
-     @see #clean(String, org.jsoup.safety.Whitelist) 
+     @see #clean(String, org.jsoup.safety.Whitelist)
      */
     public static boolean isValid(String bodyHtml, Whitelist whitelist) {
-        return new Cleaner(whitelist).isValid(parseBodyFragment(bodyHtml, ""));
+        Document doc = parseBodyFragment(bodyHtml, "");
+        if (doc.head().childNodes().size() > 0) {
+            return false;
+        }
+        if (bodyHtml.contains("<html") || bodyHtml.contains("</html>") ||
+            bodyHtml.contains("<head") || bodyHtml.contains("</head>") ||
+            bodyHtml.contains("<body")) {
+            return false;
+        }
+        // Check if parsing had to fix the HTML structure
+        String parsed = doc.body().html();
+        String inputNorm = bodyHtml.replaceAll("\"", "'").replaceAll("\\s+", "");
+        String parsedNorm = parsed.replaceAll("\"", "'").replaceAll("\\s+", "");
+        if (!inputNorm.equals(parsedNorm)) {
+            return false;
+        }
+        return new Cleaner(whitelist).isValid(doc);
     }

 }
diff --git a/src/main/java/org/jsoup/safety/Cleaner.java b/src/main/java/org/jsoup/safety/Cleaner.java
index 7e0eb28d..0e500b94 100644
--- a/src/main/java/org/jsoup/safety/Cleaner.java
+++ b/src/main/java/org/jsoup/safety/Cleaner.java
@@ -73,6 +73,10 @@ public class Cleaner {
     public boolean isValid(Document dirtyDocument) {
         Validate.notNull(dirtyDocument);

+        if (dirtyDocument.head().childNodes().size() > 0) {
+            return false;
+        }
+
         Document clean = Document.createShell(dirtyDocument.baseUri());
         int numDiscarded = copySafeNodes(dirtyDocument.body(), clean.body());
         return numDiscarded == 0;
